61	template <>
62	class aesEnc<256> : public aesTable {
63	   public:
64	    ap_uint<128> key_list[16];
65	
66	    aesEnc() {
67	#pragma HLS inline
68	#pragma HLS ARRAY_PARTITION variable = key_list complete dim = 1
69	    }
70	
71	    void updateKey(ap_uint<256> cipherkey) {
72	#pragma HLS inline off
73	        const ap_uint<8> Rcon[10] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36};
74	        ap_uint<256> lastRound = cipherkey;
75	        key_list[0] = lastRound.range(127, 0);
76	        key_list[1] = lastRound.range(255, 128);
77	        for (ap_uint<5> iter = 2; iter < 15; iter += 2) {
78	#pragma HLS pipeline II = 1
79	            //#pragma HLS pipeline II = 1
80	            ap_uint<128> currRound_0, currRound_1;
81	
82	            ap_uint<32> round_tmp = lastRound.range(255, 224);
83	            round_tmp = (round_tmp >> 8) | (round_tmp << 24);
84	
85	            round_tmp.range(7, 0) = ssbox[round_tmp.range(7, 0)] ^ Rcon[(iter >> 1) - 1];
86	            round_tmp.range(15, 8) = ssbox[round_tmp.range(15, 8)];
87	            round_tmp.range(23, 16) = ssbox[round_tmp.range(23, 16)];
88	            round_tmp.range(31, 24) = ssbox[round_tmp.range(31, 24)];
89	
90	            currRound_0.range(31, 0) = lastRound.range(31, 0) ^ round_tmp;
91	            currRound_0.range(63, 32) = lastRound.range(63, 32) ^ currRound_0.range(31, 0);
92	            currRound_0.range(95, 64) = lastRound.range(95, 64) ^ currRound_0.range(63, 32);
93	            currRound_0.range(127, 96) = lastRound.range(127, 96) ^ currRound_0.range(95, 64);
94	
95	            ap_uint<32> round_tmp2 = currRound_0.range(127, 96);
96	
97	            round_tmp2.range(7, 0) = ssbox[round_tmp2.range(7, 0)];
98	            round_tmp2.range(15, 8) = ssbox[round_tmp2.range(15, 8)];
99	            round_tmp2.range(23, 16) = ssbox[round_tmp2.range(23, 16)];
100	            round_tmp2.range(31, 24) = ssbox[round_tmp2.range(31, 24)];
101	
102	            currRound_1.range(31, 0) = lastRound.range(159, 128) ^ round_tmp2;
103	            currRound_1.range(63, 32) = lastRound.range(191, 160) ^ currRound_1.range(31, 0);
104	            currRound_1.range(95, 64) = lastRound.range(223, 192) ^ currRound_1.range(63, 32);
105	            currRound_1.range(127, 96) = lastRound.range(255, 224) ^ currRound_1.range(95, 64);
106	            lastRound.range(127, 0) = currRound_0;
107	            lastRound.range(255, 128) = currRound_1;
108	            key_list[iter] = currRound_0;
109	            key_list[iter + 1] = currRound_1;
110	        }
111	    }
112	
113	    // the function of Finite field multiplication *2
114	    static ap_uint<8> GFMul2(ap_uint<8> a) {
115	        ap_uint<8> kModulus = 0b00011011;
116	
117	        if (a[7] == 1) {
118	            a = (a << 1) ^ kModulus;
119	        } else {
120	            a <<= 1;
121	        }
122	
123	        return a;
124	    }
125	
126	    void process(ap_uint<128> plaintext, ap_uint<256> cipherkey, ap_uint<128>& ciphertext) {
127	        ap_uint<128> state, state_1;
128	        ap_uint<8> tmp_1, tmp_2_1, tmp_2_2, tmp_3;
129	        ap_uint<4> round_counter;
130	
131	        // state init and add roundkey[0]
132	        state = plaintext ^ key_list[0];
133	
134	        // Start 14 rounds of process
135	        for (round_counter = 1; round_counter <= 14; round_counter++) {
136	            // SubByte
137	            for (int i = 0; i < 16; i++) {
138	#pragma HLS unroll
139	                state(i * 8 + 7, i * 8) = ssbox[state(i * 8 + 7, i * 8)];
140	            }
141	            // ShiftRow
142	            tmp_1 = state(15, 8);
143	            state(15, 8) = state(47, 40);
144	            state(47, 40) = state(79, 72);
145	            state(79, 72) = state(111, 104);
146	            state(111, 104) = tmp_1;
147	
148	            tmp_2_1 = state(23, 16);
149	            state(23, 16) = state(87, 80);
150	            state(87, 80) = tmp_2_1;
151	
152	            tmp_2_2 = state(55, 48);
153	            state(55, 48) = state(119, 112);
154	            state(119, 112) = tmp_2_2;
155	
156	            tmp_3 = state(127, 120);
157	            state(127, 120) = state(95, 88);
158	            state(95, 88) = state(63, 56);
159	            state(63, 56) = state(31, 24);
160	            state(31, 24) = tmp_3;
161	
162	            // MixColumn
163	            for (int i = 0; i < 16; i++) {
164	#pragma HLS unroll
165	                ap_uint<8> tmp = state(i * 8 + 7, i * 8);
166	                state_1(i * 8 + 7, i * 8) = state(i * 8 + 7, i * 8);
167	            }
168	
169	            if (round_counter < 14) {
170	                // clang-format off
171	                for (int i = 0; i < 4; i++) {
172	#pragma HLS unroll
173	                    state(i * 32 + 7, i * 32) =GFMul2(state_1(i * 32 + 7, i * 32)) ^ 
174	                                               GFMul2(state_1(i * 32 + 15, i * 32 + 8))^ 
175	                                               state_1(i * 32 + 15, i * 32 + 8)^
176	                                               state_1(i * 32 + 23, i * 32 + 16) ^ 
177	                                               state_1(i * 32 + 31, i * 32 + 24);
178	                    state(i * 32 + 15, i * 32 + 8) = state_1(i * 32 + 7, i * 32) ^ 
179	                                                     GFMul2(state_1(i * 32 + 15, i * 32 + 8)) ^
180	                                                     GFMul2(state_1(i * 32 + 23, i * 32 + 16)) ^
181	                                                     state_1(i * 32 + 23, i * 32 + 16)^
182	                                                     state_1(i * 32 + 31, i * 32 + 24);
183	                    state(i * 32 + 23, i * 32 + 16) = state_1(i * 32 + 7, i * 32) ^ 
184	                                                      state_1(i * 32 + 15, i * 32 + 8) ^
185	                                                      GFMul2(state_1(i * 32 + 23, i * 32 + 16)) ^
186	                                                      GFMul2(state_1(i * 32 + 31, i * 32 + 24)) ^
187	                                                      state_1(i * 32 + 31, i * 32 + 24);
188	                    state(i * 32 + 31, i * 32 + 24) = GFMul2(state_1(i * 32 + 7, i * 32))^
189	                                                      state_1(i * 32 + 7, i * 32) ^ 
190	                                                      state_1(i * 32 + 15, i * 32 + 8) ^
191	                                                      state_1(i * 32 + 23, i * 32 + 16) ^
192	                                                      GFMul2(state_1(i * 32 + 31, i * 32 + 24));
193	                }
194	                // clang-format on
195	            } else {
196	                state = state_1;
197	            }
198	
199	            state ^= key_list[round_counter];
200	        }
201	        ciphertext = state;
202	    }
203	
204	    void updateKey_2(ap_uint<256> cipherkey) {
205	#pragma HLS inline off
206	        const ap_uint<8> Rcon[10] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36};
207	        ap_uint<128> lastRound[2];
208	        key_list[0] = cipherkey.range(127, 0);
209	        key_list[1] = cipherkey.range(255, 128);
210	        lastRound[0] = cipherkey.range(127, 0);
211	        lastRound[1] = cipherkey.range(255, 128);
212	        for (ap_uint<5> iter = 2; iter < 15; iter++) {
213	#pragma HLS pipeline II = 1
214	            ap_uint<32> round_tmp = lastRound[ap_uint<1>(1) - iter[0]].range(127, 96);
215	            if (iter[0] == ap_uint<1>(0)) {
216	                round_tmp = (round_tmp >> 8) | (round_tmp << 24);
217	            }
218	
219	            round_tmp.range(7, 0) = ssbox[round_tmp.range(7, 0)];
220	            round_tmp.range(15, 8) = ssbox[round_tmp.range(15, 8)];
221	            round_tmp.range(23, 16) = ssbox[round_tmp.range(23, 16)];
222	            round_tmp.range(31, 24) = ssbox[round_tmp.range(31, 24)];
223	
224	            if (iter[0] == ap_uint<1>(0)) {
225	                round_tmp.range(7, 0) ^= Rcon[(iter >> 1) - 1];
226	            }
227	
228	            ap_uint<128> tmp_key;
229	            tmp_key.range(31, 0) = lastRound[iter[0]].range(31, 0) ^ round_tmp;
230	            tmp_key.range(63, 32) = lastRound[iter[0]].range(63, 32) ^ tmp_key.range(31, 0);
231	            tmp_key.range(95, 64) = lastRound[iter[0]].range(95, 64) ^ tmp_key.range(63, 32);
232	            tmp_key.range(127, 96) = lastRound[iter[0]].range(127, 96) ^ tmp_key.range(95, 64);
233	
234	            key_list[iter] = tmp_key;
235	            lastRound[iter[0]] = tmp_key;
236	        }
237	    }
238	};
