240	template <>
241	class aesEnc<192> : public aesTable {
242	   public:
243	    ap_uint<128> key_list[14];
244	
245	    aesEnc() {
246	#pragma HLS inline
247	#pragma HLS ARRAY_PARTITION variable = key_list complete dim = 1
248	    }
249	
250	    void updateKey(ap_uint<192> cipherkey) {
251	#pragma HLS inline off
252	        const ap_uint<8> Rcon[10] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36};
253	        ap_uint<192> lastRound = cipherkey;
254	        key_list[0] = lastRound.range(127, 0);
255	        key_list[1].range(63, 0) = lastRound.range(191, 128);
256	        ap_uint<4> rIter = 0;
257	
258	        for (ap_uint<5> iter = 3; iter < 26; iter += 3) {
259	#pragma HLS pipeline II = 1
260	
261	            ap_uint<192> thisRound = 0;
262	
263	            ap_uint<32> round_tmp = lastRound.range(191, 160);
264	            round_tmp = (round_tmp >> 8) | (round_tmp << 24);
265	
266	            round_tmp.range(7, 0) = ssbox[round_tmp.range(7, 0)] ^ Rcon[rIter++];
267	            round_tmp.range(15, 8) = ssbox[round_tmp.range(15, 8)];
268	            round_tmp.range(23, 16) = ssbox[round_tmp.range(23, 16)];
269	            round_tmp.range(31, 24) = ssbox[round_tmp.range(31, 24)];
270	
271	            thisRound.range(31, 0) = lastRound.range(31, 0) ^ round_tmp;
272	            thisRound.range(63, 32) = lastRound.range(63, 32) ^ thisRound.range(31, 0);
273	            thisRound.range(95, 64) = lastRound.range(95, 64) ^ thisRound.range(63, 32);
274	            thisRound.range(127, 96) = lastRound.range(127, 96) ^ thisRound.range(95, 64);
275	            thisRound.range(159, 128) = lastRound.range(159, 128) ^ thisRound.range(127, 96);
276	            thisRound.range(191, 160) = lastRound.range(191, 160) ^ thisRound.range(159, 128);
277	
278	            if (iter[0] == 1) {
279	                key_list[iter.range(4, 1)].range(127, 64) = thisRound.range(63, 0);
280	                key_list[iter.range(4, 1) + 1].range(127, 0) = thisRound.range(191, 64);
281	            } else {
282	                key_list[iter.range(4, 1)].range(127, 0) = thisRound.range(127, 0);
283	                key_list[iter.range(4, 1) + 1].range(63, 0) = thisRound.range(191, 128);
284	            }
285	            lastRound = thisRound;
286	        }
287	    }
288	
289	    // the function of Finite field multiplication *2
290	
291	    static ap_uint<8> GFMul2(ap_uint<8> a) {
292	        ap_uint<8> kModulus = 0b00011011;
293	
294	        if (a[7] == 1) {
295	            a = (a << 1) ^ kModulus;
296	        } else {
297	            a <<= 1;
298	        }
299	
300	        return a;
301	    }
302	
303	    void process(ap_uint<128> plaintext, ap_uint<192> cipherkey, ap_uint<128>& ciphertext) {
304	        ap_uint<128> state, state_1;
305	        ap_uint<8> tmp_1, tmp_2_1, tmp_2_2, tmp_3;
306	        ap_uint<4> round_counter;
307	
308	        // state init and add roundkey[0]
309	        state = plaintext ^ key_list[0];
310	
311	        // Start 14 rounds of process
312	        for (round_counter = 1; round_counter <= 12; round_counter++) {
313	            // SubByte
314	            for (int i = 0; i < 16; i++) {
315	#pragma HLS unroll
316	                state(i * 8 + 7, i * 8) = ssbox[state(i * 8 + 7, i * 8)];
317	            }
318	            // ShiftRow
319	            tmp_1 = state(15, 8);
320	            state(15, 8) = state(47, 40);
321	            state(47, 40) = state(79, 72);
322	            state(79, 72) = state(111, 104);
323	            state(111, 104) = tmp_1;
324	
325	            tmp_2_1 = state(23, 16);
326	            state(23, 16) = state(87, 80);
327	            state(87, 80) = tmp_2_1;
328	
329	            tmp_2_2 = state(55, 48);
330	            state(55, 48) = state(119, 112);
331	            state(119, 112) = tmp_2_2;
332	
333	            tmp_3 = state(127, 120);
