17	/**
18	 *
19	 * @file gcm.hpp
20	 * @brief header file for Galois/Counter Mode (GCM) block cipher mode of operation.
21	 * This file is part of Vitis Security Library.
22	 *
23	 * @detail Containing GCTR encryption and decryption implementations.
24	 * GCM = GCTR + GMAC.
25	 *
26	 */
27	
28	#ifndef _XF_SECURITY_GCM_HPP_
29	#define _XF_SECURITY_GCM_HPP_
30	
31	#include <ap_int.h>
32	#include <hls_stream.h>
33	
34	#include "aes.hpp"
35	#include "gmac.hpp"
36	
37	// for debug
38	#if !defined(__SYNTHESIS__) && _XF_SECURITY_GCM_DEBUG_ == 1
39	#include <iostream>
40	#endif
41	
42	namespace xf {
43	namespace security {
44	namespace internal {
45	
46	/**
47	 *
48	 * @brief aesGctrEncrypt Encrypt plaintext to cihpertext.
49	 *
50	 * The algorithm reference is: "IEEE Standard for Authenticated Encryption with Length Expansion for Storage Devices"
51	 * The implementation is modified for better performance.
52	 *
53	 * @param plaintext The plaintext stream.
54	 * @param plaintext_length Length of plaintext in bits.
55	 * @param end_text_length Flag to signal the end of the text length stream.
56	 * @param cipherkey The cipherkey, x-bit for AES-x.
57	 * @param IV_Strm Initialization vector.
58	 * @param H_strm The hash subkey passed onto genGMAC.
59	 * @param E_K_Y0_strm E(K,Y0) as specified in standard passed onto genGMAC.
60	 * @param end_length End flag passed onto genGMAC.
61	 * @param ciphertext The ciphertext stream to output port.
62	 * @param ciphertext_length Length of ciphertext in bits to output port.
63	 * @param ciphertext1 The ciphertext stream to genGMAC.
64	 * @param ciphertext_length1 Length of ciphertext in bits to genGMAC.
65	 *
66	 */
67	
68	template <unsigned int _keyWidth = 256>
69	void aesGctrEncrypt(
70	    // stream in
71	    hls::stream<ap_uint<128> >& plaintext,
72	    hls::stream<ap_uint<64> >& plaintext_length,
73	    hls::stream<bool>& end_text_length,
74	    // input cipherkey and initilization vector
75	    hls::stream<ap_uint<_keyWidth> >& cipherkey,
76	    hls::stream<ap_uint<96> >& IV_strm,
77	    // output hash key and E(K,Y0)
78	    hls::stream<ap_uint<128> >& H_strm,
79	    hls::stream<ap_uint<128> >& E_K_Y0_strm,
80	    hls::stream<bool>& end_length,
81	    // stream out
82	    hls::stream<ap_uint<128> >& ciphertext,
83	    hls::stream<ap_uint<64> >& ciphertext_length,
84	    hls::stream<ap_uint<128> >& ciphertext1,
85	    hls::stream<ap_uint<64> >& ciphertext_length1) {
86	    bool end = end_text_length.read();
87	
88	    // inform genGMAC
89	    end_length.write(end);
90	
91	    xf::security::aesEnc<_keyWidth> cipher;
92	
93	    while (!end) {
94	#pragma HLS loop_tripcount min = 1 max = 1 avg = 1
95	        // register cipherkey
96	        ap_uint<_keyWidth> K = cipherkey.read();
97	        cipher.updateKey(K);
98	#if !defined(__SYNTHESIS__) && _XF_SECURITY_GCM_DEBUG_ == 1
99	        std::cout << std::endl << "cipherkey = " << std::hex << K << std::endl;
100	#endif
101	
102	        // generate initial counter block
103	        // XXX: The bit-width of IV is restricted to 96 in this implementation
104	        ap_uint<128> Y0;
105	        Y0.range(95, 0) = IV_strm.read();
106	        Y0.range(127, 96) = 0x01000000;
107	#if !defined(__SYNTHESIS__) && _XF_SECURITY_GCM_DEBUG_ == 1
108	        std::cout << "Y0 = " << std::hex << Y0 << std::endl;
109	#endif
110	
111	        // intermediate registers to perform the CTR encryption chain
112	        ap_uint<128> plaintext_r = 0;
113	        ap_uint<128> input_block = 0;
114	        ap_uint<128> input_block_r = 0;
115	        ap_uint<128> output_block = 0;
116	        ap_uint<128> ciphertext_r = 0;
117	
118	        // set the iteration controlling flag
119	        bool first = true;
120	        bool second = false;
121	        bool initialization = false;
122	
123	        // total text length in bits
124	        ap_uint<64> plen = plaintext_length.read();
125	
126	        // plaintext length is equal to ciphertext length
127	        ciphertext_length.write(plen);
128	        ciphertext_length1.write(plen);
129	
130	        ap_uint<64> iEnd = plen / 128 + ((plen % 128) > 0) + 2;
131	
132	    LOOP_GEN_CIPHER:
133	        for (ap_uint<64> i = 0; i < iEnd; i++) {
134	#pragma HLS loop_tripcount min = 10 max = 10 avg = 10
135	#pragma HLS PIPELINE II = 1
136	            // read a block of plaintext, 128 bits
137	            if (!first && !second) {
138	                plaintext_r = plaintext.read();
139	#if !defined(__SYNTHESIS__) && _XF_SECURITY_GCM_DEBUG_ == 1
140	                std::cout << "plaintext    = " << std::hex << plaintext_r << std::endl;
141	#endif
142	            }
143	
144	            // calculate input_block
