287	
288	template <unsigned int _keyWidth = 256>
289	void aesGctrDecrypt(
290	    // stream in
291	    hls::stream<ap_uint<128> >& ciphertext,
292	    hls::stream<ap_uint<64> >& ciphertext_length,
293	    hls::stream<bool>& end_text_length,
294	    // input cipherkey and initilization vector
295	    hls::stream<ap_uint<_keyWidth> >& cipherkey,
296	    hls::stream<ap_uint<96> >& IV_strm,
297	    // output hash key and E(K,Y0)
298	    hls::stream<ap_uint<128> >& H_strm,
299	    hls::stream<ap_uint<128> >& E_K_Y0_strm,
300	    hls::stream<bool>& end_length,
301	    // stream out
302	    hls::stream<ap_uint<128> >& ciphertext_out,
