304	    hls::stream<ap_uint<128> >& plaintext,
305	    hls::stream<ap_uint<64> >& plaintext_length) {
306	    bool end = end_text_length.read();
307	    end_length.write(end);
308	    xf::security::aesEnc<_keyWidth> cipher;
309	
310	    while (!end) {
311	#pragma HLS loop_tripcount min = 1 max = 1 avg = 1
312	        // register cipherkey
313	        ap_uint<_keyWidth> K = cipherkey.read();
314	        cipher.updateKey(K);
315	#if !defined(__SYNTHESIS__) && _XF_SECURITY_GCM_DEBUG_ == 1
316	        std::cout << std::endl << "cipherkey = " << std::hex << K << std::endl;
317	#endif
