319	        // generate initial counter block
320	        // XXX: The bit-width of IV is restricted to 96 in this implementation
321	        ap_uint<128> Y0;
322	        Y0.range(95, 0) = IV_strm.read();
323	        Y0.range(127, 96) = 0x01000000;
324	#if !defined(__SYNTHESIS__) && _XF_SECURITY_GCM_DEBUG_ == 1
325	        std::cout << "Y0 = " << std::hex << Y0 << std::endl;
326	#endif
