336	        bool first = true;
337	        bool second = false;
338	        bool initialization = false;
339	
340	        // total text length in bits
341	        ap_uint<64> clen = ciphertext_length.read();
342	
343	        // plaintext length is equal to ciphertext length
344	        ciphertext_length_out.write(clen);
345	        plaintext_length.write(clen);
346	
347	        ap_uint<64> iEnd = clen / 128 + ((clen % 128) > 0) + 2;
348	
349	    LOOP_GEN_PLAIN:
350	        for (ap_uint<64> i = 0; i < iEnd; i++) {
351	#pragma HLS loop_tripcount min = 10 max = 10 avg = 10
352	#pragma HLS PIPELINE II = 1
353	            // read a block of ciphertext, 128 bits
354	            if (!first && !second) {
355	                ciphertext_r = ciphertext.read();
356	                ciphertext_out.write(ciphertext_r);
357	#if !defined(__SYNTHESIS__) && _XF_SECURITY_GCM_DEBUG_ == 1
358	                std::cout << "ciphertext    = " << std::hex << ciphertext_r << std::endl;
359	#endif
360	            }
361	
362	            // calculate input_block
363	            if (first) { // the first iteration calculate the hash key
364	                input_block.range(127, 64) = 0x0000000000000000;
365	                input_block.range(63, 0) = 0x0000000000000000;
366	            } else if (second) { // the second iteration calculate the E(K,Y0)
367	                input_block = Y0;
368	            } else if (initialization) { // the third iteration uses Y0+1 as input_block
369	                input_block_r.range(127, 120) = Y0(7, 0);
370	                input_block_r.range(119, 112) = Y0(15, 8);
371	                input_block_r.range(111, 104) = Y0(23, 16);
372	                input_block_r.range(103, 96) = Y0(31, 24);
373	                input_block_r.range(95, 88) = Y0(39, 32);
374	                input_block_r.range(87, 80) = Y0(47, 40);
375	                input_block_r.range(79, 72) = Y0(55, 48);
376	                input_block_r.range(71, 64) = Y0(63, 56);
377	                input_block_r.range(63, 56) = Y0(71, 64);
378	                input_block_r.range(55, 48) = Y0(79, 72);
379	                input_block_r.range(47, 40) = Y0(87, 80);
380	                input_block_r.range(39, 32) = Y0(95, 88);
381	                input_block_r.range(31, 24) = Y0(103, 96);
382	                input_block_r.range(23, 16) = Y0(111, 104);
383	                input_block_r.range(15, 8) = Y0(119, 112);
384	                input_block_r.range(7, 0) = Y0(127, 120);
385	                input_block_r.range(31, 0) = input_block_r.range(31, 0) + 1;
386	                input_block.range(127, 120) = input_block_r(7, 0);
387	                input_block.range(119, 112) = input_block_r(15, 8);
388	                input_block.range(111, 104) = input_block_r(23, 16);
389	                input_block.range(103, 96) = input_block_r(31, 24);
390	                input_block.range(95, 88) = input_block_r(39, 32);
391	                input_block.range(87, 80) = input_block_r(47, 40);
392	                input_block.range(79, 72) = input_block_r(55, 48);
393	                input_block.range(71, 64) = input_block_r(63, 56);
394	                input_block.range(63, 56) = input_block_r(71, 64);
395	                input_block.range(55, 48) = input_block_r(79, 72);
396	                input_block.range(47, 40) = input_block_r(87, 80);
397	                input_block.range(39, 32) = input_block_r(95, 88);
398	                input_block.range(31, 24) = input_block_r(103, 96);
399	                input_block.range(23, 16) = input_block_r(111, 104);
400	                input_block.range(15, 8) = input_block_r(119, 112);
401	                input_block.range(7, 0) = input_block_r(127, 120);
402	                initialization = false;
403	            } else {
404	                input_block_r.range(127, 120) = input_block(7, 0);
405	                input_block_r.range(119, 112) = input_block(15, 8);
406	                input_block_r.range(111, 104) = input_block(23, 16);
407	                input_block_r.range(103, 96) = input_block(31, 24);
408	                input_block_r.range(95, 88) = input_block(39, 32);
409	                input_block_r.range(87, 80) = input_block(47, 40);
410	                input_block_r.range(79, 72) = input_block(55, 48);
411	                input_block_r.range(71, 64) = input_block(63, 56);
412	                input_block_r.range(63, 56) = input_block(71, 64);
413	                input_block_r.range(55, 48) = input_block(79, 72);
414	                input_block_r.range(47, 40) = input_block(87, 80);
415	                input_block_r.range(39, 32) = input_block(95, 88);
416	                input_block_r.range(31, 24) = input_block(103, 96);
417	                input_block_r.range(23, 16) = input_block(111, 104);
418	                input_block_r.range(15, 8) = input_block(119, 112);
