427	                input_block.range(79, 72) = input_block_r(55, 48);
428	                input_block.range(71, 64) = input_block_r(63, 56);
429	                input_block.range(63, 56) = input_block_r(71, 64);
430	                input_block.range(55, 48) = input_block_r(79, 72);
431	                input_block.range(47, 40) = input_block_r(87, 80);
432	                input_block.range(39, 32) = input_block_r(95, 88);
433	                input_block.range(31, 24) = input_block_r(103, 96);
434	                input_block.range(23, 16) = input_block_r(111, 104);
