476	 *
477	 * @brief aesGcmEncrypt Top of GCM encryption mode with AES single block cipher.
478	 *
479	 * The algorithm reference is : "IEEE Standard for Authenticated Encryption with Length Expansion for Storage Devices"
480	 * The implementation is modified for better performance.
481	 *
482	 * @tparam _keyWidth The bit-width of the cipher key, which is 128, 192, or 256.
483	 *
484	 * @param plaintext Input block stream text to be encrypted, 128 bits.
485	 * @param plaintext_length Length of plaintext in bits.
486	 * @param cipherkey Input cipher key used in encryption, x bits for AES-x.
487	 * @param IV Initialization vector.
488	 * @param AAD Additional authenticated data for calculating the tag, 128 bits.
489	 * @param AAD_length Length of AAD in bits.
490	 * @param end__length Flag to signal the end of the text length stream.
491	 * @param ciphertext Output encrypted block stream text, 128 bits.
492	 * @param ciphertext_length Length of ciphertext in bits.
493	 * @param tag The MAC.
494	 * @param end_tag End flag for the MAC.
495	 *
496	 */
497	
498	template <unsigned int _keyWidth = 256>
499	void aesGcmEncrypt(
500	    // stream in
501	    hls::stream<ap_uint<128> >& plaintext,
502	    hls::stream<ap_uint<64> >& plaintext_length,
503	    // input cipherkey, initilization vector, and additional authenticated data
504	    hls::stream<ap_uint<_keyWidth> >& cipherkey,
505	    hls::stream<ap_uint<96> >& IV,
506	    hls::stream<ap_uint<128> >& AAD,
507	    hls::stream<ap_uint<64> >& AAD_length,
508	    hls::stream<bool>& end_length,
509	    // stream out
510	    hls::stream<ap_uint<128> >& ciphertext,
511	    hls::stream<ap_uint<64> >& ciphertext_length,
512	    // ouput tag
513	    hls::stream<ap_uint<128> >& tag,
514	    hls::stream<bool>& end_tag) {
515	#pragma HLS DATAFLOW
516	
517	    hls::stream<ap_uint<128> > H_strm("H_strm");
518	#pragma HLS RESOURCE variable = H_strm core = FIFO_LUTRAM
519	#pragma HLS STREAM variable = H_strm depth = 32
520	
521	    hls::stream<ap_uint<128> > E_K_Y0_strm("E_K_Y0_strm");
522	#pragma HLS RESOURCE variable = E_K_Y0_strm core = FIFO_LUTRAM
523	#pragma HLS STREAM variable = E_K_Y0_strm depth = 32
524	
525	    hls::stream<bool> end_length_strm("end_length_strm");
526	#pragma HLS RESOURCE variable = end_length_strm core = FIFO_LUTRAM
527	#pragma HLS STREAM variable = end_length_strm depth = 32
528	
529	    hls::stream<ap_uint<128> > ciphertext_strm("ciphertext_strm");
530	#pragma HLS RESOURCE variable = ciphertext_strm core = FIFO_LUTRAM
531	#pragma HLS STREAM variable = ciphertext_strm depth = 32
532	
533	    hls::stream<ap_uint<64> > ciphertext_length_strm("ciphertext_length_strm");
534	#pragma HLS RESOURCE variable = ciphertext_length_strm core = FIFO_LUTRAM
535	#pragma HLS STREAM variable = ciphertext_length_strm depth = 32
536	
537	    aesGctrEncrypt<_keyWidth>(plaintext, plaintext_length, end_length, cipherkey, IV, H_strm, E_K_Y0_strm,
538	                              end_length_strm, ciphertext_strm, ciphertext_length_strm, ciphertext, ciphertext_length);
539	
540	    genGMAC(AAD, AAD_length, ciphertext_strm, ciphertext_length_strm, H_strm, E_K_Y0_strm, end_length_strm, tag,
541	            end_tag);
542	
543	} // end aesGcmEncrypt
