587	#pragma HLS STREAM variable = H_strm depth = 32
588	
589	    hls::stream<ap_uint<128> > E_K_Y0_strm("E_K_Y0_strm");
590	#pragma HLS RESOURCE variable = E_K_Y0_strm core = FIFO_LUTRAM
591	#pragma HLS STREAM variable = E_K_Y0_strm depth = 32
