template <int lW, int keyLen>
void expandStrm(hls::stream<bool>& eInStrm, hls::stream<bool>& eOutStrm, hls::stream<ap_uint<lW> >& lenStrm) {
    while (!eInStrm.read()) {
        eOutStrm.write(false);
